const nav=[['dashboard','⌂','总览'],['orders','▤','工单'],['tasks','◉','维保'],['devices','▦','设备']];

function orders(items,h){return items.map(order=>`<article class="field-order" data-searchable="${h(`${order.id} ${order.title} ${order.device}`)}"><div class="field-order-top"><span class="field-order-id">${h(order.id)} / ${h(order.time)}</span><span class="field-priority ${order.priority==='紧急'?'urgent':''}">${h(order.priority)}</span></div><h3>${h(order.title)}</h3><p>${h(order.device)} · ${h(order.location)}</p><div class="field-order-bottom"><span class="field-state">${h(order.status)}</span><button type="button" data-action="open-order" data-id="${h(order.id)}">处理工单 <b aria-hidden="true">↗</b></button></div></article>`).join('');}
function tasks(items,h){return items.map(task=>`<article class="field-task" data-searchable="${h(`${task.title} ${task.device}`)}"><div class="field-task-glyph">${task.status==='已完成'?'✓':'◎'}</div><div><small>${h(task.id)} · ${h(task.due)}</small><h3>${h(task.title)}</h3><p>${h(task.device)} · ${h(task.steps)} · ${h(task.owner)}</p></div>${task.status==='待执行'?`<button type="button" data-action="complete-task" data-id="${h(task.id)}">完成 ↗</button>`:'<span class="field-completed">已完成</span>'}</article>`).join('');}
function devices(items,h){return items.map(device=>`<article class="field-device" data-searchable="${h(`${device.code} ${device.name} ${device.place}`)}"><div class="field-device-icon">${h(device.kind.slice(0,1))}</div><div class="field-device-text"><span>${h(device.code)} / ${h(device.kind)}</span><h3>${h(device.name)}</h3><p>${h(device.place)}</p></div><strong class="field-device-status">${h(device.health)}</strong><button type="button" data-action="open-device" data-id="${h(device.id)}">查看 ↗</button></article>`).join('');}

function dashboard(m,h){return `<section class="field-hero"><div class="field-hero-inner"><div class="field-hero-kicker"><span>本班次</span> · 2026年09月29日</div><h1>现场任务，<br>现在处理。</h1><p>先看异常设备和紧急工单，再完成到期维保。</p><div class="field-hero-actions"><button type="button" data-action="new-report">＋ 现场报修</button><button type="button" data-action="nav" data-view="tasks">查看点检任务 ↗</button></div></div><div class="field-hero-orb"><div class="field-orb-ring"><strong>${m.activeOrders}</strong><span>未关闭工单</span></div></div></section>
  <section class="field-stat-row" aria-label="演示概览"><div><span>待执行任务</span><strong>${m.pendingTasks}</strong><small>项</small></div><div><span>紧急工单</span><strong>${m.urgentOrders}</strong><small>件</small></div><div><span>在册设备</span><strong>${m.devices.length}</strong><small>台</small></div></section>
  <div class="field-section-head"><div><small>01 / RIGHT NOW</small><h2>需要你关注</h2></div><button type="button" data-action="nav" data-view="orders">全部工单 ↗</button></div><div class="field-order-grid">${orders(m.orders.filter(item=>item.status!=='已关闭').slice(0,3),h)}</div>
  <div class="field-section-head"><div><small>02 / ON THE FLOOR</small><h2>接下来的点检</h2></div><button type="button" data-action="nav" data-view="tasks">查看计划 ↗</button></div><div class="field-tasks">${tasks(m.tasks.slice(0,3),h)}</div>`;}
function ordersView(m,h){return `<header class="field-page-head"><small>WORK ORDERS / 维修现场</small><h1>工单队列</h1><p>按优先级推进，点开卡片就能继续流转。</p><button type="button" data-action="new-report">＋ 新建报修</button></header><div class="field-list-tools"><div class="field-filters">${[['all','全部'],['待派单','待派单'],['维修中','维修中'],['待验收','待验收']].map(([value,label])=>`<button type="button" data-action="filter" data-filter="${value}" class="${m.filter===value?'active':''}">${label}</button>`).join('')}</div><input data-search-input type="search" aria-label="搜索工单" placeholder="搜索工单或设备"></div><div class="field-order-grid field-full-grid">${orders(m.ordersInView,h)}</div>`;}
function tasksView(m,h){return `<header class="field-page-head"><small>MAINTENANCE / 保养点检</small><h1>今日任务</h1><p>从计划走到现场，按设备逐项完成。</p></header><div class="field-tasks field-full-tasks">${tasks(m.tasks,h)}</div>`;}
function devicesView(m,h){return `<header class="field-page-head"><small>ASSETS / 设备档案</small><h1>设备清单</h1><p>快速查找设备，查看位置与状态，直接发起报修。</p><button type="button" data-action="new-report">＋ 快速报修</button></header><div class="field-list-tools"><span>已建档 ${m.devices.length} 台设备</span><input data-search-input type="search" aria-label="搜索设备" placeholder="按设备名称、编号搜索"></div><div class="field-device-grid">${devices(m.devices,h)}</div>`;}

const css=`<style>
.field{--modal-bg:#fff;--modal-ink:#25324a;--modal-soft:#f1f4fa;--modal-accent:#4768d3;--modal-muted:#7c8da5;--modal-line:#e3e9f1;min-height:100vh;background:#eef1f7;color:#24324c;font-family:Inter,"Microsoft YaHei",system-ui,sans-serif}.field button{font:inherit}.field-shell{min-height:100vh;padding:61px 20px 120px}.field-main{max-width:1130px;margin:auto}.field-header{max-width:1130px;margin:0 auto 22px;display:flex;align-items:center;justify-content:space-between;gap:12px}.field-logo{display:flex;gap:10px;align-items:center}.field-logo-symbol{width:33px;height:33px;border-radius:11px;background:#4263c7;color:white;display:grid;place-items:center;font-weight:700}.field-logo strong{font-size:14px;letter-spacing:.04em}.field-logo small{display:block;font-size:9px;color:#8d9ab0;margin-top:2px}.field-head-actions{display:flex;align-items:center;gap:9px}.field-head-actions>span{color:#9eacc0;font-size:10px}.field-head-actions button{position:relative;border:1px solid #dbe2ef;background:#fff;color:#5a75bc;border-radius:11px;width:37px;height:37px;font-size:15px}.field-head-actions em{position:absolute;right:-5px;top:-6px;border-radius:10px;background:#f68474;color:white;font-style:normal;font-size:9px;padding:1px 5px}.field-hero{background:linear-gradient(118deg,#2b448d,#4d69bd 60%,#637ad0);border-radius:22px;min-height:313px;color:white;display:grid;grid-template-columns:1.4fr 1fr;overflow:hidden;position:relative;box-shadow:0 15px 30px #435daa23}.field-hero:before{content:"";position:absolute;width:510px;height:510px;border-radius:50%;border:1px solid #ffffff2b;right:-106px;top:-175px}.field-hero:after{content:"";position:absolute;width:330px;height:330px;border-radius:50%;border:1px solid #ffffff35;right:28px;top:-25px}.field-hero-inner{padding:33px 40px 38px;z-index:1}.field-hero-kicker{font-size:11px;color:#d7e2ff}.field-hero-kicker span{color:#ffc8b8;font-weight:700}.field-hero h1{font-size:38px;line-height:1.26;letter-spacing:-.04em;margin:19px 0 10px}.field-hero p{font-size:12px;color:#cbd6fa;margin:0}.field-hero-actions{display:flex;gap:10px;margin-top:27px}.field-hero-actions button{border:0;border-radius:11px;min-height:43px;padding:10px 16px;font-size:12px;font-weight:700;background:#fff;color:#3652a2}.field-hero-actions button:nth-child(2){background:#ffffff24;color:#fff;border:1px solid #ffffff4b}.field-hero-orb{display:grid;place-items:center;position:relative;z-index:1}.field-orb-ring{width:196px;height:196px;border:19px solid #fff2;border-top-color:#fff9;border-right-color:#ffbeb0;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;transform:rotate(-12deg)}.field-orb-ring>*{transform:rotate(12deg)}.field-orb-ring strong{font-size:63px;line-height:1;font-weight:700}.field-orb-ring span{font-size:12px;color:#dfe8ff;margin-top:5px}.field-stat-row{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:16px 0 31px}.field-stat-row>div{background:#fff;border:1px solid #e2e8f1;border-radius:16px;min-height:96px;padding:18px 21px;display:flex;align-items:center;gap:7px;box-shadow:0 3px 14px #58698d08}.field-stat-row span{margin-right:auto;color:#8190aa;font-size:11px}.field-stat-row strong{font-size:32px;color:#304eab;line-height:1}.field-stat-row small{font-size:11px;color:#91a0b8;align-self:end;padding-bottom:3px}.field-section-head{display:flex;align-items:end;justify-content:space-between;margin:30px 0 16px}.field-section-head small,.field-page-head small{font-size:10px;font-weight:700;color:#7b90b6;letter-spacing:.13em}.field-section-head h2{font-size:21px;margin:6px 0 0;letter-spacing:-.02em}.field-section-head button{border:0;background:transparent;color:#4666bd;font-size:11px;font-weight:700;padding:6px}.field-order-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.field-order{background:#fff;border:1px solid #e2e8f1;border-radius:16px;padding:20px;box-shadow:0 7px 20px #5a6b900a;min-height:211px;display:flex;flex-direction:column}.field-order-top,.field-order-bottom{display:flex;align-items:center;justify-content:space-between;gap:8px}.field-order-id{font-size:10px;color:#8d9db5;letter-spacing:.04em}.field-priority{font-size:10px;color:#637bb8;background:#eef2fc;border-radius:7px;padding:5px 8px}.field-priority.urgent{color:#c76652;background:#fff0ea}.field-order h3{font-size:16px;line-height:1.4;margin:19px 0 7px;font-weight:700}.field-order p{color:#8695af;font-size:11px;line-height:1.5;margin:0 0 20px}.field-order-bottom{margin-top:auto;border-top:1px solid #edf0f6;padding-top:13px}.field-state{font-size:10px;color:#6075a3}.field-order-bottom button{border:0;background:#ebeffa;color:#3e5ca9;border-radius:8px;min-height:31px;padding:7px 9px;font-size:11px;font-weight:700}.field-order-bottom b{font-size:14px;margin-left:6px}.field-tasks{display:grid;gap:9px}.field-task{display:flex;gap:15px;align-items:center;min-height:77px;padding:15px 20px;background:#fff;border:1px solid #e1e8f1;border-radius:14px}.field-task-glyph{width:40px;height:40px;border-radius:12px;background:#e9eefb;color:#6581d0;display:grid;place-items:center;font-size:20px;flex:none}.field-task>div:nth-child(2){flex:1;min-width:0}.field-task small{font-size:10px;color:#91a0b8}.field-task h3{font-size:13px;margin:5px 0 3px}.field-task p{font-size:10px;color:#93a0b6;margin:0}.field-task>button{border:0;border-radius:8px;background:#4567ca;color:#fff;padding:8px 12px;font-size:11px;font-weight:700}.field-completed{color:#72a184;font-size:11px}.field-dock{position:fixed;bottom:18px;left:50%;transform:translateX(-50%);z-index:900;display:flex;gap:5px;border:1px solid #e4eafa;background:#fffffff0;backdrop-filter:blur(12px);padding:6px;border-radius:18px;box-shadow:0 15px 45px #25376d2b}.field-dock button{border:0;background:transparent;color:#8c9bb8;min-width:78px;min-height:49px;border-radius:12px;display:grid;place-items:center;gap:2px;font-size:10px;padding:4px 9px}.field-dock button span{font-size:18px;line-height:1}.field-dock button[aria-current=page]{background:#e8eefb;color:#395ab6;font-weight:700}.field-page-head{position:relative;margin:9px 0 23px}.field-page-head h1{font-size:30px;margin:8px 0 7px;letter-spacing:-.03em}.field-page-head p{color:#8b9bb2;font-size:12px;margin:0}.field-page-head>button{position:absolute;right:0;bottom:0;border:0;background:#4668c9;color:white;border-radius:10px;padding:10px 15px;font-size:11px;font-weight:700}.field-list-tools{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:15px;color:#8898ae;font-size:11px}.field-list-tools input{width:250px;border:1px solid #dee6f2;border-radius:10px;background:#fff;padding:10px 12px;color:#344f86;font-size:11px}.field-filters{display:flex;gap:7px;flex-wrap:wrap}.field-filters button{border:1px solid #dce5f1;border-radius:8px;background:#fff;color:#8294ae;padding:9px 12px;font-size:11px}.field-filters button.active{background:#4767c7;border-color:#4767c7;color:#fff}.field-full-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.field-full-tasks{margin-top:23px}.field-device-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.field-device{background:#fff;border:1px solid #e2e8f2;border-radius:16px;padding:20px;display:flex;align-items:center;gap:14px;flex-wrap:wrap}.field-device-icon{width:48px;height:48px;border-radius:14px;background:#e9eef9;color:#4969ba;display:grid;place-items:center;font-weight:700}.field-device-text{min-width:0;flex:1}.field-device-text span{color:#9aa8bd;font-size:10px}.field-device-text h3{margin:5px 0;font-size:14px}.field-device-text p{margin:0;color:#9aa7ba;font-size:10px}.field-device-status{border-radius:8px;background:#edf3f5;color:#68848e;padding:5px 8px;font-size:10px;font-weight:500}.field-device button{border:0;background:#eef2fb;color:#4b67ac;border-radius:8px;padding:8px 10px;font-size:11px;font-weight:700}.field .proto-modal{border-radius:19px}.field .proto-modal-actions button{border-radius:10px}@keyframes field-enter{from{opacity:0;transform:translateY(9px)}to{opacity:1;transform:translateY(0)}}.field-main>*{animation:field-enter 230ms ease-out both}
@media(max-width:920px){.field-order-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.field-hero-orb{opacity:.78}.field-stat-row>div{padding:15px}}
@media(max-width:650px){.field-shell{padding:65px 13px 115px}.field-header{margin-bottom:16px}.field-head-actions>span{display:none}.field-hero{display:block;min-height:0}.field-hero-inner{padding:25px}.field-hero h1{font-size:30px}.field-hero-orb{display:none}.field-stat-row{gap:7px}.field-stat-row>div{display:block;min-height:84px;padding:12px}.field-stat-row span{display:block;font-size:10px;white-space:nowrap}.field-stat-row strong{display:inline-block;font-size:26px;margin-top:8px}.field-stat-row small{margin-left:3px}.field-order-grid,.field-full-grid,.field-device-grid{grid-template-columns:1fr}.field-order{min-height:187px}.field-task{padding:12px;gap:10px}.field-task h3{font-size:12px}.field-task>button{padding:8px}.field-page-head>button{position:static;margin-top:13px}.field-list-tools{display:block}.field-list-tools input{margin-top:10px;width:100%}.field-dock{bottom:10px;width:calc(100% - 20px);justify-content:space-around}.field-dock button{min-width:0;flex:1}.field-section-head{margin:25px 0 13px}}
@media(prefers-reduced-motion:reduce){.field-main>*{animation:none}}
</style>`;

export default {
  className:'field',
  render(m,h){return `${css}<div class="field-shell"><header class="field-header"><div class="field-logo"><span class="field-logo-symbol">维</span><div><strong>设备维保</strong><small>FIELD WORKSPACE</small></div></div><div class="field-head-actions"><span>试点工厂 · 演示数据</span><button type="button" data-action="notifications" aria-label="消息中心">◌${m.unread?`<em>${m.unread}</em>`:''}</button></div></header><div class="field-main">${m.view==='dashboard'?dashboard(m,h):m.view==='orders'?ordersView(m,h):m.view==='tasks'?tasksView(m,h):devicesView(m,h)}</div><nav class="field-dock" aria-label="工作区导航">${nav.map(([view,icon,label])=>`<button type="button" data-action="nav" data-view="${view}" ${m.view===view?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${label}</button>`).join('')}</nav></div>`;}
};
